import json,os,pwd,subprocess
from pathlib import Path
assert os.geteuid()==0 and os.environ.get('SUDO_USER')=='likimk'
uid=pwd.getpwnam('likimk').pw_uid
u=['runuser','-u','likimk','--','env',f'XDG_RUNTIME_DIR=/run/user/{uid}',f'DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/{uid}/bus']
def run(a):
 r=subprocess.run(a,capture_output=True,text=True,timeout=10);return {'exit':r.returncode,'stdout':r.stdout,'stderr':r.stderr}

import time
run(u+['systemctl','--user','stop','f8-speaker-volume.service'])
files={'/usr/share/f8-pro/audio/f8-speaker-volume.conf': '', '/usr/libexec/f8-pro/speaker-volume-service.py': '', '/etc/systemd/user/f8-speaker-volume.service': '', '/etc/xdg/autostart/f8-speaker-volume.desktop': 'W0Rlc2t0b3AgRW50cnldClR5cGU9QXBwbGljYXRpb24KTmFtZT1GOCBTcGVha2VyIFZvbHVtZSBDdXJ2ZQpFeGVjPXN5c3RlbWN0bCAtLXVzZXIgc3RhcnQgZjgtc3BlYWtlci12b2x1bWUuc2VydmljZQpOb0Rpc3BsYXk9dHJ1ZQpYLUtERS1hdXRvc3RhcnQtcGhhc2U9MQ0K', '/usr/share/f8-pro/audio/f8-soft-volume.c': '', '/usr/share/f8-pro/audio/ladspa.h': ''}
import base64
backup=Path('/var/lib/f8-pro/backups/speaker-volume-v1');backup.mkdir(parents=True,exist_ok=True)
if not (backup/'before.json').exists():(backup/'before.json').write_text(json.dumps({'sinks':run(u+['pactl','--format=json','list','sinks']),'default':run(u+['pactl','get-default-sink'])}))
for name,content in files.items():
 p=Path(name)
 if p.exists() and not (backup/name.lstrip('/')).exists():
  b=backup/name.lstrip('/');b.parent.mkdir(parents=True,exist_ok=True);b.write_bytes(p.read_bytes())
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(content));p.chmod(0o644)
Path('/usr/lib/f8-pro').mkdir(parents=True,exist_ok=True)
r=run(['gcc','-O2','-shared','-fPIC','-Wall','-Wextra','-Werror','-Wl,-z,relro,-z,now','-o','/usr/lib/f8-pro/f8-soft-volume.so','/usr/share/f8-pro/audio/f8-soft-volume.c','-lm']);assert r['exit']==0,r
for args in [['systemctl','--user','daemon-reload'],['systemctl','--user','enable','--now','f8-speaker-volume.service']]:
 r=run(u+args);assert r['exit']==0,r
for _ in range(30):
 d=run(u+['pactl','get-default-sink'])
 if d['stdout'].strip()=='f8-speaker-volume':break
 time.sleep(.3)
time.sleep(1)
print(json.dumps({'service':run(u+['systemctl','--user','status','f8-speaker-volume.service','--no-pager']),'default':run(u+['pactl','get-default-sink']),'sinks':run(u+['pactl','--format=json','list','sinks']),'plugin_b64':base64.b64encode(Path('/usr/lib/f8-pro/f8-soft-volume.so').read_bytes()).decode(),'controls':{n:run(['amixer','-c','0','sget',n]) for n in ['PCM','Output 2']}}))
